.media-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.media-card{min-width:0;overflow:hidden;border:1px solid #ece9f0;border-radius:12px;background:#fff;transition:transform .18s,box-shadow .18s,border-color .18s}.media-card:hover{transform:translateY(-3px);border-color:#e2dced;box-shadow:0 10px 22px rgba(37,29,48,.07)}.preview-wrap{position:relative;overflow:hidden;background:#f0eef4;aspect-ratio:16/10}.preview{display:block;width:100%;height:100%;object-fit:cover;transition:transform .3s}.media-card:hover .preview{transform:scale(1.025)}.preview-placeholder{display:grid;place-items:center;width:100%;height:100%;background:linear-gradient(135deg,#f7f3ee,#e8f2fa);color:#7e96aa;font-size:30px}.media-type-badge{position:absolute;top:10px;left:10px;padding:5px 8px;border-radius:6px;background:#fffe;color:#393441;font-size:9px;font-weight:800;box-shadow:0 2px 8px #1e243015}.publish-badge{position:absolute;right:10px;top:10px;padding:5px 8px;border-radius:6px;background:#e9f8ef;color:#228558;font-size:9px;font-weight:800}.publish-badge.draft{background:#fff1dc;color:#9a6b18}.media-card-body{padding:13px}.media-card h3{margin:0 0 4px;overflow:hidden;color:#302b38;font-size:13px;font-weight:800;text-overflow:ellipsis;white-space:nowrap}.media-card .subtitle{min-height:16px;margin:0 0 12px;overflow:hidden;color:#96909d;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.media-meta{display:flex;align-items:center;gap:5px;flex-wrap:wrap;margin-bottom:13px}.pill{display:inline-flex;align-items:center;max-width:100%;overflow:hidden;padding:4px 7px;border-radius:6px;background:#f5f3f8;color:#777181;font-size:9px;text-overflow:ellipsis;white-space:nowrap}.media-card-actions{display:flex;gap:6px;padding-top:11px;border-top:1px solid #f0edf3}.media-card-actions .button{flex:1;padding:8px 7px;font-size:10px}.empty-state{grid-column:1/-1;padding:45px 16px;border:1px dashed #e3deea;border-radius:12px;color:#96909d;text-align:center;font-size:11px}.empty-state strong{display:block;margin-bottom:5px;color:#494353;font-size:13px}
