<label class="field hidden" id="url-field">Lien YouTube ou Vimeo<input name="external_url" type="url" placeholder="https://youtu.be/..."></label>
<label class="field" id="file-field">Fichier média<input name="media" id="media-file" type="file" accept="image/jpeg,image/png,image/webp" required><span class="hint" id="file-hint">JPG, PNG ou WebP — 10 Mo maximum.</span></label>
<div class="row"><label class="field">Ordre d’affichage<input name="sort_order" type="number" value="0" min="-100000" max="100000" required></label><label class="field"><span><input name="is_published" type="checkbox"> Publier sur le site</span><span class="hint">Les brouillons restent visibles uniquement dans l’administration.</span></label></div>
<label class="field"><span><input name="is_hero" type="checkbox"> Utiliser comme image de fond du hero</span><span class="hint">Disponible uniquement pour les photos publiées. Vous pouvez sélectionner plusieurs images pour le diaporama d’accueil.</span></label>
<div class="actions"><button class="button" type="submit" id="save-button">Enregistrer le média</button></div><p class="notice" id="form-status" role="status"></p>
</form></section>
<section class="panel"><div class="panel-head"><div><h2>Bibliothèque de médias</h2><p>Prévisualisez, recherchez et gérez les ressources de votre site.</p></div></div><div class="media-toolbar"><div class="media-toolbar-left"><input id="media-search" type="search" placeholder="Rechercher un média…" aria-label="Rechercher un média"><select id="filter" aria-label="Filtrer les médias"><option value="all">Tous les médias</option><option value="image">Photos</option><option value="video">Vidéos</option><option value="draft">Brouillons</option><option value="published">Publiés</option></select></div><span class="hint" id="media-result-count">0 média</span></div><div class="media-summary"><span class="summary-chip">Photos <strong id="summary-images">0</strong></span><span class="summary-chip">Vidéos <strong id="summary-videos">0</strong></span><span class="summary-chip">Publiés <strong id="summary-published">0</strong></span></div><div class="media-grid" id="media-list"></div></section></main></div></div><script>
(() => {
const $=s=>document.querySelector(s); let csrf=''; let items=[]; let circuits=[]; let regions=[];
const api=path=>'../api/'+path;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function notice(t){$('#notice').textContent=t||'';}
async function request(path,options={}){const headers={'Accept':'application/json',...(options.mutate?{'X-CSRF-Token':csrf}:{}),...(options.json?{'Content-Type':'application/json'}:{})};const r=await fetch(api(path),{credentials:'same-origin',...options,headers});const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p.error?.message||'Une erreur est survenue.');return p;}
function show(session){csrf=session.csrfToken||'';$('#login-screen').classList.add('hidden');$('#dashboard').classList.remove('hidden');loadItems();}
async function session(){try{const r=await request('admin/session.php');if(r.data.authenticated)show(r.data);}catch(_){}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-status').textContent='Connexion…';const f=new FormData(e.currentTarget);try{const r=await request('admin/session.php',{method:'POST',json:true,body:JSON.stringify({email:f.get('email'),password:f.get('password')})});$('#login-status').textContent='';show(r.data);}catch(err){$('#login-status').textContent=err.message;}});
$('#logout').addEventListener('click',async()=>{try{await request('admin/session.php',{method:'POST',json:true,mutate:true,body:JSON.stringify({action:'logout'})});}catch(_){}location.reload();});
function updateSourceFields(){const type=$('#media-type').value, source=$('#video-source').value;const editing=Boolean($('#media-form').elements.id.value);$('#video-source').closest('.field')?.classList.toggle('hidden',type!=='video');$('#url-field').classList.toggle('hidden',type!=='video'||source!=='external');$('#file-field').classList.toggle('hidden',type==='video'&&source==='external');$('#alt-field').classList.toggle('hidden',type!=='image');const file=$('#media-file');file.accept=type==='image'?'image/jpeg,image/png,image/webp':'video/mp4,video/webm';file.required=!editing&&!(type==='video'&&source==='external');$('#file-hint').textContent=type==='image'?'JPG, PNG ou WebP — 10 Mo maximum.':'MP4 ou WebM — 100 Mo maximum.';$('#url-field').querySelector('input').required=type==='video'&&source==='external';}
$('#media-type').addEventListener('change',updateSourceFields);$('#video-source').addEventListener('change',updateSourceFields);
function resetForm(){const f=$('#media-form');f.reset();f.elements.id.value='';$('#form-title').textContent='Ajouter un média';$('#save-button').textContent='Enregistrer le média';$('#cancel-edit').classList.add('hidden');$('#form-status').textContent='';updateSourceFields();}
$('#cancel-edit').addEventListener('click',()=>{resetForm();$('#media-form-panel').classList.add('hidden');});
function startNewMedia(type){resetForm();$('#media-form-panel').classList.remove('hidden');$('#media-type').value=type;$('#video-source').value='external';updateSourceFields();$('#media-form').scrollIntoView({behavior:'smooth',block:'start'});(type==='video'?$('#url-field input'):$('#media-file')).focus({preventScroll:true});}
$('#add-photo').addEventListener('click',()=>startNewMedia('image'));
$('#add-video').addEventListener('click',()=>startNewMedia('video'));
function render(){const filter=$('#filter').value;const query=($('#media-search')?.value||'').trim().toLocaleLowerCase('fr');const visible=items.filter(i=>{const matchesFilter=filter==='all'||(filter==='draft'?!i.is_published:filter==='published'?i.is_published:i.media_type===filter);const text=[i.title_fr,i.title_en,i.description_fr,i.description_en,i.circuit_title_fr,i.region,i.source_type].filter(Boolean).join(' ').toLocaleLowerCase('fr');return matchesFilter&&(!query||text.includes(query));});const images=items.filter(i=>i.media_type==='image').length;const videos=items.filter(i=>i.media_type==='video').length;const published=items.filter(i=>Boolean(i.is_published)).length;[['kpi-total',items.length],['kpi-images',images],['kpi-videos',videos],['kpi-published',published],['kpi-draft-note',items.length-published+' brouillon(s)'],['summary-images',images],['summary-videos',videos],['summary-published',published],['media-result-count',visible.length+(visible.length===1?' média':' médias')]].forEach(([id,value])=>{const node=document.getElementById(id);if(node)node.textContent=value;});$('#media-list').innerHTML=visible.map(i=>{const preview=i.thumbnail_path||i.file_path;const src=preview?(preview.startsWith('http')||preview.startsWith('/')?preview:'../'+preview):'';const isVideo=i.media_type==='video';return '<article class="media-card"><div class="preview-wrap">'+(src?'<img class="preview" loading="lazy" src="'+esc(src)+'" alt="'+esc(i.alt_text||i.title_fr||'')+'">':'<div class="preview-placeholder">'+(isVideo?'▷':'▧')+'</div>')+'<span class="media-type-badge">'+(isVideo?'▶ Vidéo':'▧ Photo')+'</span><span class="publish-badge '+(i.is_published?'':'draft')+'">'+(i.is_published?'Publié':'Brouillon')+'</span></div><div class="media-card-body"><h3 title="'+esc(i.title_fr)+'">'+esc(i.title_fr)+'</h3><p class="subtitle">'+esc(i.title_en||i.description_fr||'Aucune description')+'</p><div class="media-meta"><span class="pill">'+esc(i.circuit_title_fr||'Galerie générale')+'</span><span class="pill">'+esc(i.source_type||'Fichier')+'</span></div><div class="media-card-actions"><button class="button secondary" data-edit="'+i.id+'">Modifier</button><button class="button secondary" data-toggle="'+i.id+'">'+(i.is_published?'Masquer':'Publier')+'</button><button class="button secondary" data-delete="'+i.id+'">Supprimer</button></div></div></article>';}).join('')||'<div class="empty-state"><strong>'+(items.length?'Aucun résultat':'Votre galerie est vide')+'</strong>'+(items.length?'Essayez un autre filtre ou une autre recherche.':'Ajoutez votre première photo ou vidéo de Madagascar.')+'</div>';$('#media-list').querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>edit(Number(b.dataset.edit))));$('#media-list').querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>toggle(Number(b.dataset.toggle))));$('#media-list').querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>remove(Number(b.dataset.delete))));}
function renderCircuitOptions(){const select=$('#circuit-id');const current=select.value;select.innerHTML='<option value="">Galerie générale — Madagascar</option>'+circuits.map(c=>'<option value="'+c.id+'">'+esc(c.title_fr||c.slug)+(c.is_published?'':' (brouillon)')+'</option>').join('');select.value=current;}
function renderRegionOptions(){const select=$('#media-region');const current=select.value;select.innerHTML='<option value="">Toutes les régions / galerie générale</option>'+regions.map(r=>'<option value="'+esc(r.option_value)+'">'+esc(r.option_label)+'</option>').join('');select.value=current;}
async function loadItems(){try{const r=await request('admin/gallery.php');items=r.data;circuits=r.circuits||[];regions=r.regions||[];renderCircuitOptions();renderRegionOptions();render();}catch(e){notice(e.message);}}
function edit(id){const item=items.find(i=>i.id===id);if(!item)return;$('#media-form-panel').classList.remove('hidden');const f=$('#media-form');f.reset();f.elements.id.value=item.id;f.elements.media_type.value=item.media_type;$('#video-source').value=item.source_type==='upload'?'upload':'external';for(const k of ['title_fr','title_en','description_fr','description_en','alt_text','sort_order'])f.elements[k].value=item[k]??(k==='sort_order'?0:'');f.elements.circuit_id.value=item.circuit_id??'';f.elements.region.value=item.region??'';f.elements.external_url.value=item.external_url||'';f.elements.is_published.checked=item.is_published;f.elements.is_hero.checked=Boolean(item.is_hero);$('#form-title').textContent='Modifier le média';$('#save-button').textContent='Enregistrer les modifications';$('#cancel-edit').classList.remove('hidden');$('#form-status').textContent='';updateSourceFields();$('#media-file').required=false;$('#media-form').scrollIntoView({behavior:'smooth',block:'start'});}
async function toggle(id){const i=items.find(x=>x.id===id);if(!i)return;const body={id,media_type:i.media_type,circuit_id:i.circuit_id,region:i.region||null,title_fr:i.title_fr,title_en:i.title_en,description_fr:i.description_fr,description_en:i.description_en,alt_text:i.alt_text,sort_order:i.sort_order,is_published:!i.is_published,is_hero:Boolean(i.is_hero)};if(i.media_type==='video')body.external_url=i.external_url;try{await request('admin/gallery.php',{method:'PATCH',json:true,mutate:true,body:JSON.stringify(body)});notice('Publication mise à jour.');await loadItems();}catch(e){notice(e.message);}}
async function remove(id){if(!confirm('Supprimer définitivement ce média ?'))return;try{await request('admin/gallery.php?id='+id,{method:'DELETE',mutate:true});notice('Média supprimé.');await loadItems();}catch(e){notice(e.message);}}
$('#filter').addEventListener('change',render);$('#media-search').addEventListener('input',render);
$('#media-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const id=f.elements.id.value;const type=f.elements.media_type.value;const source=$('#video-source').value;const status=$('#form-status');status.textContent='Enregistrement…';try{let result;if(!id&&!(type==='video'&&source==='external')){const data=new FormData(f);data.delete('video-source');data.set('media_type',type);data.set('circuit_id',f.elements.circuit_id.value);data.set('is_published',f.elements.is_published.checked?'1':'0');data.set('is_hero',f.elements.is_hero.checked?'1':'0');result=await request('admin/gallery.php',{method:'POST',mutate:true,body:data});}else{const body={media_type:type,circuit_id:f.elements.circuit_id.value||null,region:f.elements.region.value||null,title_fr:f.elements.title_fr.value.trim(),title_en:f.elements.title_en.value.trim()||null,description_fr:f.elements.description_fr.value.trim()||null,description_en:f.elements.description_en.value.trim()||null,alt_text:f.elements.alt_text.value.trim()||null,sort_order:Number(f.elements.sort_order.value||0),is_published:f.elements.is_published.checked,is_hero:f.elements.is_hero.checked};if(id)body.id=Number(id);if(type==='video'&&source==='external')body.external_url=f.elements.external_url.value.trim();else if(!id){status.textContent='Choisissez un fichier média ou un lien vidéo.';return;}result=await request('admin/gallery.php',{method:id?'PATCH':'POST',json:true,mutate:true,body:JSON.stringify(body)});}status.textContent='';notice('Média enregistré.');resetForm();$('#media-form-panel').classList.add('hidden');await loadItems();}catch(err){status.textContent=err.message;}});
updateSourceFields();session();
})();
</script></body></html>
